NAME = 'Est: Estonian Bible'
BOOK = 'Philippians'

CHAPTERS = {
    1: {
        1: 'Paulus ja Timoteos, Kristuse Jeesuse sulased, kõigile pühadele Kristuses Jeesuses, kes elavad Filipis, ja ühtlasi koguduse juhatajaile ja abilistele.',
        2: 'Armu teile ja rahu Jumalalt, meie Isalt, ja Issandalt Jeesuselt Kristuselt!',
        3: 'Ma tänan oma Jumalat iga kord, kui ma teid meelde tuletan,',
        4: 'alati igas oma palves teie kõikide eest rõõmuga palvetades;',
        5: 'ma tänan teie osaduse pärast Evangeeliumiga esimesest päevast siiani;',
        6: 'ja olen kindel selles, et See, Kes teis on alustanud hea töö, viib selle lõpule Kristuse Jeesuse päevani.',
        7: 'Nõnda ongi mulle õige seda teist kõigist mõtelda, sest ma kannan teid oma südames, kes te kõik siis, kui ma olen ahelais, ja ka siis, kui kaitsen Evangeeliumi ja seda kinnitan, ühes minuga olete armu osalised.',
        8: 'Sest Jumal on mu tunnistaja, kuidas ma teid kõiki igatsen Kristuse Jeesuse südamlikkusega.',
        9: 'Ja seda ma palun Jumalalt, et teie armastus veel rohkem ja rohkem kasvaks selges tunnetamises ja kõiges tajumises,',
        10: 'et te võiksite kindlaks teha, mis on peaasi, ja oleksite puhtad ning laitmatud Kristuse päevaks,',
        11: 'täis õiguse vilja, mis tuleb Jeesuse Kristuse läbi, Jumala austuseks ja kiituseks.',
        12: 'Aga ma tahan teada anda teile, vennad, et see, mis minuga on juhtunud, on andnud Evangeeliumile veel rohkem hoogu,',
        13: 'nõnda et kogu kohtukojas ja kõigile muile on saanud avalikuks, et ma olen ahelais Kristuse pärast',
        14: 'ja et suurem osa vendi mu ahelate tõttu on saanud vahvaks Issandas ja palju rohkem julgevad kartmatult rääkida Jumala sõna.',
        15: 'Mõned küll kuulutavad Kristust kadeduse ja riiu pärast, kuid mõned ka hea meelega.',
        16: 'Teised kuulutavad armastusest, teades, et ma viibin siin Evangeeliumi kaitsmiseks,',
        17: 'teised aga kuulutavad Kristust kiusu pärast, mitte puhtast meelest; nad ju mõtlevad suurendada minu vangipõlve viletsust.',
        18: 'Aga mis sellest? Kui aga Kristust kuulutatakse igal kombel, olgu silmakirjaks, olgu tõemeelega, ja sellest ma rõõmutsen ja tahan ka edaspidi rõõmutseda;',
        19: 'sest ma tean, et see tuleb mulle päästeks teie palve kaudu ja Jeesuse Kristuse Vaimu abil',
        20: 'minu kindlat ootust ja lootust mööda, et ma milleski ei jää häbisse, vaid et Kristus nüüdki, nagu ikka, täie julgusega saab auliseks minu ihus, olgu elu või surma läbi.',
        21: 'Sest minule on elamine Kristus ja suremine kasu.',
        22: 'Aga kui lihas elamine on tulusam mu tööle, siis ma ei tea, kumba valida.',
        23: 'Mind tõmbab nii see kui teine: ma himustan siit lahkuda ja olla Kristuse juures, sest see on hoopis palju parem;',
        24: 'aga lihasse jäämine on vajalikum teie pärast.',
        25: 'Ja selles veendumuses ma tean, et ma jään lihasse ja jään teie kõikide juurde teie usu eduks ja rõõmuks,',
        26: 'et teie kiitlemine oleks rohke Kristuses Jeesuses minu läbi selle tõttu, et ma jälle tulen teie juurde.',
        27: 'Ainult käituge Kristuse Evangeeliumi vääriliselt, et ma, olgu tulles ja teid nähes või tulemata jäädes, kuuleksin teist, et te püsite ühes vaimus ja ühel meelel minuga võitlete Evangeeliumi usu eest',
        28: 'ega lase endid heidutada mitte millestki vastaste poolt. See on neile hukatuse, teile aga pääste tähiseks, ja nimelt Jumalalt.',
        29: 'Sest teile on armust antud Kristuse pärast mitte ainult uskuda Temasse, vaid ka kannatada Tema pärast',
        30: 'ja võidelda sama võitlust, mida te olete näinud minust ja nüüd minust kuulete.',
    },
    2: {
        1: 'Kui nüüd mingisugune manitsus Kristuses, kui mingisugune armastuse troost, kui mingisugune Vaimu osadus, kui mingisugune südamlikkus ja kaastundmus kehtib,',
        2: 'siis tehke mu rõõm täielikuks sellega, et mõtlete sama ja peate ühesugust armastust, olles üksmeelsed ja ühemõttelised',
        3: 'ega tee midagi riiu ega tühja au pärast, vaid arvate alanduses üksteist ülemaks kui iseennast,',
        4: 'ja et ükski ei vaata selle peale, mis on tulus temale, vaid ka selle peale, mis on tulus teistele.',
        5: 'Olgu teil samasugune meel, mis oli ka Kristusel Jeesusel,',
        6: 'Kes, kuigi ta oli Jumala nägu, ei arvanud saagiks olla Jumalaga ühesugune,',
        7: 'vaid loobus Iseenese olust ning võttis orja näo, saades inimeste sarnaseks; ja Ta leiti välimuselt inimesena;',
        8: 'Ta alandas iseennast, saades sõnakuulelikuks surmani, pealegi ristisurmani.',
        9: 'Sellepärast ongi Jumal Tema ülendanud kõrgele ja andnud Temale nime üle kõigi nimede,',
        10: 'et Jeesuse nimes nõtkuksid kõik põlved, niihästi taevaliste kui maapealsete kui ka maa-aluste omad,',
        11: 'ja iga keel tunnistaks, et Jeesus Kristus on Issand, Jumala Isa auks.',
        12: 'Nõnda siis, mu armsad, otsekui te ikka olete olnud sõnakuulelikud, mitte üksnes nagu siis, kui ma olin teie juures, vaid ka nüüd veel rohkem minu ära olles, nõudke oma päästet kartuse ja värinaga!',
        13: 'Sest Jumal on See, kes teis on tegev, et te tahate ja tegutsete Tema hea meele järgi.',
        14: 'Tehke kõik nurisemata ja kaksipidi mõtlemata,',
        15: 'et te oleksite laitmatud ja puhtad, veatud Jumala lapsed keset tigedat ja pöörast sugupõlve, kelle seas teie paistate otsekui taevatähed maailmas,',
        16: 'hoides elu sõna, minule kiitluseks Kristuse päeval, et ma ei ole tühja jooksnud ega teinud tühja tööd.',
        17: 'Ja kuigi minu veri peaks kahjana valatama teie usu ohvri ja jumalateenistuse üle, siiski ma rõõmutsen ja olen rõõmus ühes teie kõikidega.',
        18: 'Sellesama pärast olge ka teie rõõmsad ja rõõmutsege ühes minuga.',
        19: 'Ma loodan Issandas Jeesuses Timoteose varsti läkitada teie juurde, et ka minul oleks hea meel teada saades, kuidas teie käsi käib.',
        20: 'Sest mul pole kedagi muud nii üksmeelset minuga, kes nõnda tõsiselt hoolitseks teie eest.',
        21: 'Sest nad kõik otsivad eneste oma, aga mitte seda, mis on Kristuse Jeesuse Oma.',
        22: 'Aga tema ustavust te teate, sest nagu laps oma isaga, nõnda on ta minuga ühes töötanud Evangeeliumi kasuks.',
        23: 'Teda ma loodan nüüd läkitada, niipea kui näen, kuidas minu asi areneb.',
        24: 'Ent mul on kindel lootus Issandas, et ma ka ise varsti tulen.',
        25: 'Aga ma olen arvanud tarviliseks läkitada teie juurde vend Epafroditose, oma kaastöölise ja kaasvõitleja, teie Apostli ja minu vajaduste eest hoolitseja,',
        26: 'sellepärast et ta teid kõiki igatses ja suurt tuska tundis sellest, et olite kuulnud tema haigestumisest.',
        27: 'Sest tema oli ka tõesti suremas haige; ent Jumal andis temale armu, aga mitte üksi temale, vaid ka minule, et mulle ei tuleks kurbust kurbuse peale.',
        28: 'Sellepärast ma läkitasin tema seda nobedamini, et te teda nähes jälle rõõmustuksite ja mul oleks vähem kurbust.',
        29: 'Siis võtke ta vastu Issandas kõige rõõmuga ja pidage niisuguseid mehi kalliks.',
        30: 'Sest Kristuse töö pärast oli ta surma suus ega hoolinud oma elust, et täita seda, mis teil jäi tegemata hoolitsemises minu eest.',
    },
    3: {
        1: 'Peale kõige, mu vennad, rõõmutsege Issandas! Üht ja sama kirjutades ei tüüta see mind, aga teid see kinnitab.',
        2: 'Pidage silmas koeri, pidage silmas kurje töötegijaid, hoiduge katkilõikamise eest!',
        3: 'Sest ümberlõigatud, need oleme meie, kes Jumalat teenime vaimus, ja kiitleme Kristusest Jeesusest ega looda liha peale,',
        4: 'ehkki mul oleks lootust liha peale. Kui keegi muu arvab, et tema võib liha peale loota, siis mina veel rohkem!',
        5: 'Ma olen ümber lõigatud kaheksandal päeval, ma olen Iisraeli soost, Benjamini suguharust, ma olen heebrealane, sündinud heebrealasist, käsuõpetuselt variser,',
        6: 'innukas koguduse tagakiusaja, laitmatu käsuõiguse poolest.',
        7: 'Aga mis mulle oli kasuks, olen ma arvanud kahjuks Kristuse pärast.',
        8: 'Jah tõesti, mina arvan kõik kahjuks oma Issanda Kristuse Jeesuse ülivõimsa tunnetuse vastu, Kelle pärast ma olen minetanud kõik selle ja pean kõike pühkmeiks, et kasuks saada Kristust',
        9: 'ja et mind leitaks Tema seest ega oleks mul oma õigust, mis on käsust, vaid see õigus, mis tuleb Kristuse usu kaudu, see, mis tuleb Jumalalt usu varal,',
        10: 'et ma tunneksin ära Tema ja Ta ülestõusmise väe ja Tema kannatamise osaduse ning muutuksin Tema surma sarnaseks,',
        11: 'kui ma kuidagi pääsen ülestõusmisele surnute seast.',
        12: 'Ei mitte, et ma selle juba oleksin kätte saanud või oleksin juba täiuslik, vaid ma püüan kätte saada seda, mille pärast Kristus Jeesus mind on kätte saanud.',
        13: 'Vennad, mina ei arva seda juba kätte saanud olevat; ent üht ma ütlen: ma unustan ära, mis on taga, ja sirutun sinnapoole, mis on ees,',
        14: 'ma pürin seatud eesmärgi poole, taevase kutsumise võiduhinna poole Kristuses Jeesuses.',
        15: 'Nii mitu nüüd, kui meid on täiuslikku, mõelgem sama! Ja kui te midagi mõtlete teisiti, siis Jumal ilmutab teile ka selle.',
        16: 'Ometi, kuhu oleme jõudnud, sealt käigem sama teed!',
        17: 'Järgige minu eeskuju, vennad, ja vaadelge neid, kes elavad nõnda nagu meie teile eeskujuks oleme.',
        18: 'Sest paljud, kellest ma teile olen sagedasti öelnud ja nüüd ütlen ka nuttes, elavad Kristuse risti vaenlastena.',
        19: 'Nende ots on hukatus, nende jumal on nende kõht ja nende au on nende häbis; nad taotlevad maapealseid asju.',
        20: 'Sest meie ühiskond on teavas, kust me ka ootame Issandat Jeesust Kristust kui Õnnistegijat,',
        21: 'Kes meie alanduse ihu muudab Oma äraseletatud ihu sarnaseks väge mööda, millega Ta võib ka kõik teha Oma alamaks.',
    },
    4: {
        1: 'Nõnda, mu armsad ja igatsetud vennad, minu rõõm ja pärg, seiske siis Issandas kindlatena, armsad!',
        2: 'Euodiat ma manitsen ja ma manitsen Süntühhet olema ühemõttelised Issandas.',
        3: 'Ja ma palun ka sind, tõsine kaastööline, aita neid naisi, kes on võidelnud Evangeeliumi eest ühes minuga ja Kleemensiga ja mu teiste abimeestega, kelle nimed on eluraamatus.',
        4: 'Olge ikka rõõmsad Issandas! Ja taas ma ütlen: olge rõõmsad.',
        5: 'Teie leebus saagu teatavaks kõigile inimestele. Issand on lähedal.',
        6: 'Ärge muretsege ühtigi, vaid laske kõiges oma palumised palve ja anumisega ühes tänuga saada Jumalale teatavaks.',
        7: 'Ja Jumala rahu, mis on ülem kõigest mõistusest, hoiab teie südamed ja mõtted Kristuses Jeesuses.',
        8: 'Viimaks, vennad, kõik, mis on tõsine, mis aus, mis õige, mis kasin, mis armas, mis on hea kuulda kui vooruslik komme ja kiituse väärt, sellele mõelge!',
        9: 'Mis te ka olete õppinud ja saanud ja kuulnud ja näinud minult, seda tehke; ja rahu Jumal on siis teiega.',
        10: 'Väga suureks rõõmuks Issandas aga oli mulle see, et te juba uuesti virgusite mõtlema minule: sellele te mõtlesite ennegi, aga teil ei olnud juhust selleks.',
        11: 'Ma ei ütle seda puuduse pärast; sest ma olen õppinud olema rahul sellega, mis mul on.',
        12: 'Oskan elada vähesega ja oskan elada külluses, olen kõigega ja kõigi oludega harjunud: nii olema söönud kui ka nägema nälga, elama nii külluses kui ka puuduses.',
        13: 'Ma suudan kõik Temas, Kes mind teeb vägevaks.',
        14: 'Siiski te tegite hästi, et mind toetasite minu viletsuses.',
        15: 'Ent teiegi, filiplased, teate, et armuõpetuse algusaegadest, kui ma läksin teele Makedooniast, ükski Kogudus ei olnud osaduses minuga andmise ja võtmise arvepidamises kui ainult teie,',
        16: 'sest Tessaloonikassegi te saatsite minu tarviduseks ühe ja teise korra.',
        17: 'Mitte, et ma andi püüan, vaid ma otsin vilja, mis kasuks oleks teie arvele.',
        18: 'Mul on nüüd kõike ja mul on rohkesti; ma sain küllalt, kui ma Epafroditoselt võtsin vastu, mis teie olite lähetanud magusa lõhnana ja armsa ohvrina, mis on Jumalale meelepärast.',
        19: 'Aga küll minu Jumal täidab kõik teie vajaduse Oma rikkust mööda auga Kristuses Jeesuses.',
        20: 'Aga Jumalale ja meie Isale olgu austus ajastute ajastuteni! Aamen.',
        21: 'Tervitage kõiki pühasid Kristuses Jeesuses! Teid tervitavad minu juures olevad vennad.',
        22: 'Kõik pühad saadavad teile tervitusi, aga iseäranis need, kes on keisri perest.',
        23: 'Meie Issanda Jeesuse Kristuse arm olgu teie vaimuga!',
    },
}
